  const decisions = [
    ['ADR-42','Quality gate là điều kiện đóng phase Menu 4 cấp','Phase chỉ hoàn tất khi bảy suite Menu, full regression, 10 route middleware, 21 migration và menus:check cùng đạt; kiểm thử bao gồm legacy 2 cấp, cây 4 cấp, security và query bounds.'],
    ['ADR-41','Menu operations dùng kiểm tra chỉ đọc và rollback giữ dữ liệu','Seeder duyệt defaults đệ quy nhưng chỉ seed location trống, transaction thất bại nếu vượt max depth. menus:check chỉ báo invariant bằng exit code; rollback code không xóa hoặc tái cấu trúc node cấp 3–4.'],
    ['ADR-40','Storefront Menu dùng renderer đệ quy theo ngữ cảnh','Desktop, mobile và footer nhận cùng published DTO depth 1–4 nhưng dùng partial trình bày riêng. Desktop chỉ điều khiển direct submenu và tự đổi hướng theo viewport; mobile dùng details lồng nhau; không query dữ liệu trong Blade.'],
    ['ADR-39','Move branch là mutation riêng có stale guard','Metadata edit không đổi parent/location. Move lock subject, descendants, ancestor và sibling scopes; payload mang source parent/location để phát hiện dữ liệu cũ, ghi một menu.moved event và chỉ leaf được đổi location.'],
    ['ADR-38','Admin Menu phân trang root và dựng metadata cây trong bộ nhớ','Danh sách eager-load tối đa bốn cấp rồi render recursive row; search/status descendant trả root cùng ancestor context. Parent selector tính depth/breadcrumb/subtree exclusion từ một collection thay vì query từng node, còn MenuService vẫn là validation cuối.'],
    ['ADR-37','Published Menu 4 cấp dùng eager-load hữu hạn và cache v2','Service tải root cộng ba relation children, trả DTO có depth và giới hạn tối đa bốn query menu/location khi cache lạnh. Prefix v2 ngăn cache DTO hai cấp cũ tồn tại qua deploy.'],
    ['ADR-36','Menu 4 cấp tách metadata edit khỏi move branch','Depth và subtree height được tính động trên adjacency list. Move dùng mutation riêng, chặn subject/descendant/cấp 5/khác location; chỉ leaf được đổi location. Published tree eager-load cố định tới cấp 4 để query không tăng theo số node.'],
    ['ADR-35','Menu nhiều cấp giới hạn tối đa 4','Giữ adjacency list parent_id và tính depth/subtree động; không lưu cột depth. Một branch chỉ được move khi depth parent mới cộng chiều cao subtree không vượt 4; cây vô hạn và mega-menu nằm ngoài phase.'],
    ['ADR-34','Quality gate là điều kiện đóng phase Menu','Phase chỉ hoàn tất khi sáu suite Menu, full regression, 8 route middleware và 21 migration đều đạt; permission revocation phải có hiệu lực ở request kế tiếp, còn accessibility được kiểm tra bằng markup/JS/CSS contract bên cạnh feature rendering.'],
    ['ADR-33','Menu defaults backfill theo ranh giới location','Seeder chỉ tạo toàn bộ cây khi location hoàn toàn trống; không merge defaults vào location đã có dữ liệu. Identity gồm parent, link destination và nhãn để giữ các item khác tên nhưng cùng route; fallback khẩn cấp dùng chung defaults và mặc định tắt.'],
    ['ADR-32','Storefront menu resolve tại layout và render theo location','Provider chỉ resolve header/footer một lần ở layout; desktop/mobile dùng chung cây header, footer dùng cây riêng. Active state áp sau cache theo request; fallback config được giữ tạm đến khi seeder/backfill Task 6.7 hoàn tất.'],
    ['ADR-31','Menu quick actions giữ HTML fallback','Status/reorder dùng form PATCH chuẩn và được JavaScript tăng cường bằng fetch; reorder gửi toàn bộ sibling scope, backend lock/validate lại và chỉ invalid cache sau transaction thành công.'],
    ['ADR-30','Menu admin phân trang theo root','Danh sách eager-load child và paginate root để không tách cây qua hai trang; filter/search chọn cây phù hợp, còn parent option chỉ nhận root cùng location và service kiểm tra invariant lần cuối.'],
    ['ADR-29','Settings quality gate là điều kiện kết thúc phase','Mọi mở rộng registry phải giữ ma trận quyền, update/audit nguyên tử, cache request kế tiếp, không credential leakage và tối đa một query settings trên request consumer khi cache lạnh.'],
    ['ADR-28','Settings backfill chỉ bổ sung dữ liệu thiếu','Schema key-value hiện tại được giữ nguyên; seeder/--fix-missing dùng insert-only, còn key lạ, giá trị sai và asset mồ côi chỉ được báo để người vận hành xác minh trước khi xử lý.'],
    ['ADR-27','Email private, SEO/social public có guard','Tên gửi/recipient đọc qua private settings nhưng transport credential ở env; indexing cần production + setting, canonical/OG/social chỉ nhận http(s), auto-reply khóa đến khi có queue/retry.'],
    ['ADR-26','Settings presentation không thay snapshot nghiệp vụ','Branding/contact/seller invoice và currency được resolve lúc render qua presenter/formatter; người nhận, item, SKU, giá và tổng tiền vẫn lấy snapshot đơn hàng. Locale không hỗ trợ fallback về vi.'],
    ['ADR-25','Menu mutation và cache đi qua một service','Permission/tree/link guards và audit chạy trong transaction; cache published chỉ xóa sau commit, còn active state được tính sau cache theo request. Seeder chỉ backfill menus.* khi role vẫn đúng baseline cũ.'],
    ['ADR-24','Menu storefront dùng contract allowlist','Location chỉ header/footer; link type route/url/none, route nội bộ chỉ từ allowlist, URL qua scheme/admin-path validation; cây tối đa 2 cấp, desktop/mobile dùng cùng nguồn published và cache chỉ xóa sau commit.'],
    ['ADR-23','System assets chỉ xóa file managed','Upload dùng prefix riêng; file cũ xóa sau commit, upload mới xóa khi rollback, URL ngoài/path module khác được giữ nguyên.'],
    ['ADR-22','Settings UI cập nhật từng group','Form Request dựng validation từ registry, checkbox được normalize; image chỉ qua upload workflow và view-only không thể submit.'],
    ['ADR-21','Settings cache một typed map','Mọi consumer đọc qua SystemSettingService; group update ghi audit trong transaction rồi mới invalid cache, decimal được giữ dạng string.'],
    ['ADR-20','Runtime settings không thay hạ tầng','Locale/timezone settings chỉ chi phối presentation sau middleware/formatter; APP_KEY, SMTP, DB, cache, queue và session tiếp tục do env/config quản lý.'],
    ['ADR-19','Settings dùng registry do code quản lý','Database chỉ lưu value; key/type/default/validation/publicity nằm trong config registry và secret tiếp tục ở env/secret manager.'],
    ['ADR-07','Role quản trị phải được nhận diện bằng dữ liệu','Bổ sung roles.is_admin để role tùy chỉnh hoạt động mà không sửa danh sách PHP tĩnh.'],
    ['ADR-08','Permission catalog do code quản lý','UI chỉ sync permission vào role; không tạo hoặc xóa permission tùy ý trong giai đoạn đầu.'],
    ['ADR-09','Mọi thay đổi IAM phải có audit','Sync user-role và role-permission chạy trong transaction, ghi before/after nhưng loại bỏ secret.'],
    ['ADR-10','Chỉ super admin quản trị cấu trúc quyền','Admin quản lý tài khoản không phải super admin; role và permission matrix chỉ do super admin thay đổi.'],
    ['ADR-11','Gate bypass chỉ dành cho permission','Ability dạng module.action dùng RBAC bypass; policy theo đối tượng vẫn kiểm tra safeguard kể cả với super admin.'],
    ['ADR-12','Role được gán không vượt quá actor','Non-super admin chỉ gán role quản trị có tập permission nằm trong quyền hiệu lực của chính mình; self-update không được đổi role/trạng thái.'],
    ['ADR-13','Không hard-delete tài khoản có dấu vết nghiệp vụ','IAM chỉ xóa cứng tài khoản chưa phát sinh quan hệ; nếu có orders/history/settings/audit/cart/wishlist thì chuyển blocked để giữ attribution.'],
    ['ADR-14','Tách CRUD role khỏi permission matrix','Task 4.7 chỉ quản lý metadata role; role mới chưa có permission và được cấu hình nguyên tử ở Task 4.8.'],
    ['ADR-15','Chỉ super_admin bất biến','Super Admin được sửa role khác và xóa khi chưa gán user; tên role chuẩn vẫn khóa, seeder không ghi đè permission đã tùy chỉnh.'],
    ['ADR-16','Audit UI là append-only và phòng thủ hai lớp','Không cung cấp route sửa/xóa; payload được sanitize khi ghi và áp allowlist/denylist lần nữa khi hiển thị dữ liệu legacy.'],
    ['ADR-17','Thu hồi quyền có hiệu lực ở request kế tiếp','Middleware và helper truy vấn quyền hiện tại từ database; không cache permission trong session nên gỡ role/permission không cần đăng nhập lại.'],
    ['ADR-18','Role và permission được lưu bằng một form nguyên tử','Create/update role sync pivot và ghi audit snapshot trong cùng transaction; endpoint sync riêng được giữ để tương thích ngược.'],
    ['ADR-01','Customer là user không thuộc ADMIN_ROLES','Giữ một bảng users nhưng loại tài khoản quản trị khỏi truy vấn khách hàng.'],
    ['ADR-02','Order item lưu snapshot','Tên, SKU và giá không thay đổi theo catalog sau khi đặt hàng.'],
    ['ADR-03','Trừ kho tại confirmed','Pending chưa giữ tồn; hủy sau confirmed sẽ hoàn tồn đúng một lần.'],
    ['ADR-04','Lưu order status history','Mỗi chuyển trạng thái có người thực hiện, ghi chú và thời gian để audit.'],
    ['ADR-05','Invoice dùng browser print trước','Tránh dependency PDF khi nhu cầu hiện tại chỉ là in hóa đơn.'],
    ['ADR-06','Timezone nghiệp vụ UTC+7','Laravel dùng Asia/Ho_Chi_Minh và database session dùng +07:00.']
  ];
